body.script:
// =========================================================================
// RESUME BUILDER LOGIC
// =========================================================================
function flashBtn(btn, msg) {
if (!btn) return;
var orig = btn.getAttribute("data-orig") || btn.innerHTML;
btn.setAttribute("data-orig", orig);
btn.innerHTML = "✓ " + (msg || "AI Applied!");
setTimeout(function() { btn.innerHTML = orig; }, 900);
}

function switchTab(id) {
var tabs = ["resume", "notes", "resizer", "typing"];
for (var i = 0; i < tabs.length; i++) {
var sec = document.getElementById("tab-" + tabs[i]);
var b = document.getElementById("btn-" + tabs[i]);
if (sec) sec.classList.add("hidden");
if (b) b.className = "tab-btn flex-1 px-3.5 py-2 text-xs font-bold rounded-xl text-slate-600 cursor-pointer whitespace-nowrap";
}
var activeSec = document.getElementById("tab-" + id);
var activeBtn = document.getElementById("btn-" + id);
if (activeSec) activeSec.classList.remove("hidden");
if (activeBtn) activeBtn.className = "tab-btn flex-1 px-3.5 py-2 text-xs font-bold rounded-xl bg-indigo-600 text-white cursor-pointer whitespace-nowrap";
}

function updateCV() {
var name = document.getElementById("f-name").value || "YOUR FULL NAME";
var role = document.getElementById("f-role").value || "";
var phone = document.getElementById("f-phone").value || "";
var email = document.getElementById("f-email").value || "";
var addr = document.getElementById("f-addr").value || "";

document.getElementById("out-name").innerText = name;
document.getElementById("out-sign").innerText = "(" + name + ")";
document.getElementById("out-role").innerText = role;
document.getElementById("out-contact").innerText = phone + " | " + email + " | " + addr;
document.getElementById("out-summary").innerText = document.getElementById("f-summary").value;
document.getElementById("out-exp").innerText = document.getElementById("f-exp").value;
document.getElementById("out-edu").innerText = document.getElementById("f-edu").value;
document.getElementById("out-skills").innerText = document.getElementById("f-skills").value;
document.getElementById("out-personal").innerText = document.getElementById("f-personal").value;
}

function applyEduScores() {
var g = document.getElementById("edu-grad-score").value.trim() || "72% / 6.8 CGPA";
var tw = document.getElementById("edu-12-score").value.trim() || "76% (First Division)";
var tn = document.getElementById("edu-10-score").value.trim() || "80% (8.0 CGPA)";

var formattedEdu = "• Bachelor's Degree (Graduation) – Recognized University | Score: " + g + "\n" +
"• Intermediate (12th Standard) – State / Central Board | Score: " + tw + "\n" +
"• High School (10th Standard) – State / Central Board | Score: " + tn;

document.getElementById("f-edu").value = formattedEdu;
updateCV();
}

