var currentActiveCategory = "all";

function getAllNotesList() {
var saved = [];
try {
saved = JSON.parse(localStorage.getItem("freecv_uploaded_notes") || "[]");
} catch (e) { saved = []; }
return saved.concat(defaultStudyNotesData);
}

function renderStudyNotes() {
var searchInput = document.getElementById("mainNotesSearch");
var clearBtn = document.getElementById("clearSearchBtn");
var statusEl = document.getElementById("searchStatusText");
var container = document.getElementById("studyNotesContainer");
if (!container) return;

var query = (searchInput ? searchInput.value : "").toLowerCase().trim();
if (clearBtn) clearBtn.style.display = query.length > 0 ? "block" : "none";

var allNotes = getAllNotesList();

var filtered = allNotes.filter(function(item) {
var matchesCat = currentActiveCategory === "all" || (item.categories && item.categories.includes(currentActiveCategory));
if (!query) return matchesCat;
var fullText = (item.title + " " + item.desc + " " + (item.keywords || "") + " " + item.badge).toLowerCase();
var words = query.split(/\s+/);
var matchesSearch = words.every(function(w) { return fullText.includes(w); });
return matchesCat && matchesSearch;
});

if (statusEl) {
statusEl.innerText = query
? '🔍 "' + searchInput.value + '" के लिए ' + filtered.length + ' नोट्स मिले:'
: '📚 कुल उपलब्ध स्टडी नोट्स (' + filtered.length + ')';
}

if (filtered.length === 0) {
container.innerHTML = <div class="col-span-full bg-white rounded-2xl p-8 text-center border border-slate-200 shadow-sm"> <p class="text-slate-700 font-bold mb-2">😕 "${searchInput.value}" से जुड़ा कोई नोट्स नहीं मिला।

कृपया भूगोल, अर्थव्यवस्था, इतिहास, संविधान, Static GK, GDP, नदियाँ आदि कीवर्ड सर्च करें।
सभी नोट्स दिखाएँ (Show All)

`;
return;
}

container.innerHTML = filtered.map(function(note) {
return <div class="bg-white rounded-2xl p-5 border border-slate-200 shadow-sm hover:shadow-md transition flex flex-col justify-between"> <div> <span class="inline-block bg-indigo-50 text-indigo-700 text-xs font-extrabold px-3 py-1 rounded-md mb-3">${note.badge}



{note.desc}






✍️ FreeCV Study Hub
👁️ {note.url}" class="block w-full bg-indigo-600 hover:bg-indigo-700 text-white text-center text-xs sm:text-sm font-extrabold py-3.5 rounded-xl shadow transition">
📖 ऑनलाइन नोट पढ़ें (Read & Switch Notes)



`;
}).join("");
}

