}

// UPLOAD NOTES MODAL FUNCTIONS
function openUploadNotesModal() {
document.getElementById("uploadNotesModal").style.display = "flex";
}

function closeUploadNotesModal() {
document.getElementById("uploadNotesModal").style.display = "none";
}

function saveCustomNote(e) {
e.preventDefault();
var title = document.getElementById("upNoteTitle").value.trim();
var badge = document.getElementById("upNoteBadge").value.trim();
var cat = document.getElementById("upNoteCategory").value;
var desc = document.getElementById("upNoteDesc").value.trim();
var keywords = document.getElementById("upNoteKeywords").value.trim();
var urlInput = document.getElementById("upNoteUrl").value.trim() || "#";

var newNote = {
id: "custom-" + Date.now(),
title: title,
badge: badge.toUpperCase(),
url: urlInput,
views: "New Upload",
categories: ["all", cat],
desc: desc,
keywords: keywords + " " + title + " " + badge
};

var saved = [];
try {
saved = JSON.parse(localStorage.getItem("freecv_uploaded_notes") || "[]");
} catch (err) { saved = []; }
saved.unshift(newNote);
localStorage.setItem("freecv_uploaded_notes", JSON.stringify(saved));

closeUploadNotesModal();
e.target.reset();
renderStudyNotes();
}

// =========================================================================
// EXAM PHOTO & SIGN RESIZER LOGIC
// =========================================================================
var rawExamImg = null;
var outExamUrl = "";

function loadExamFile(e) {
var file = e.target.files[0];
if (!file) return;
var r = new FileReader();
r.onload = function(ev) {
var im = new Image();
im.onload = function() {
rawExamImg = im;
drawExamPhoto();
};
im.src = ev.target.result;
};
r.readAsDataURL(file);
}

function drawExamPhoto() {
var c = document.getElementById("p-canvas");
if (!c) return;
var ctx = c.getContext("2d");
var type = document.getElementById("p-type").value;
var nm = document.getElementById("p-name").value.trim();
var dt = document.getElementById("p-date").value.trim();
var q = parseInt(document.getElementById("p-qual").value) / 100;

c.width = (type === "photo") ? 350 : 400;
c.height = (type === "photo") ? 450 : 200;

ctx.fillStyle = "#ffffff";
ctx.fillRect(0, 0, c.width, c.height);

if (rawExamImg) {
ctx.drawImage(rawExamImg, 0, 0, c.width, c.height);
}

if (type === "photo" && (nm || dt)) {
ctx.fillStyle = "#ffffff";
ctx.fillRect(0, c.height - 65, c.width, 65);
ctx.fillStyle = "#000000";
ctx.textAlign = "center";
ctx.font = "bold 19px Arial";
ctx.fillText(nm.toUpperCase(), c.width / 2, c.height - 38);
ctx.font = "bold 17px Arial";
ctx.fillText(dt.toUpperCase(), c.width / 2, c.height - 12);
}

outExamUrl = c.toDataURL("image/jpeg", q);
var kb = Math.round(((outExamUrl.length - 22) * 0.75) / 1024);
var kbEl = document.getElementById("p-kb");
if (kbEl) kbEl.innerText = "Ready File Size: ~" + kb + " KB";
}

function saveExamPhoto() {
if (!rawExamImg) { alert("Pehle photo select karein!"); return; }
var a = document.createElement("a");
a.href = outExamUrl;
a.download = "Exam_Photo_Ready.jpg";
a.click();
}

