var typingPassages = {
ssc: [
"Success in competitive examinations requires consistent daily practice, time management, and high accuracy. Digital literacy and fast typing speed have become essential skills for modern administrative roles across India."
],
economy: [
"Quick commerce and modern supply chain networks have transformed urban retail across India. Automated fulfillment centers, barcode scanners, and real-time inventory tracking allow products to reach customers within minutes."
]
};

var tyTimer = null;
var tyLeft = 60;
var tyRunning = false;

function aiChangeTypingText(btn) {
document.getElementById("ty-text").innerText = "Success in competitive examinations requires consistent daily practice, time management, and high accuracy. Digital literacy and fast typing speed have become essential skills for modern administrative roles across India.";
resetTypingTest();
if (btn) flashBtn(btn, "Words Changed!");
}

function runTyping() {
var inp = document.getElementById("ty-input").value;
var tgt = document.getElementById("ty-text").innerText;
if (!tyRunning && inp.length > 0) {
tyRunning = true;
tyTimer = setInterval(function() {
tyLeft--;
document.getElementById("ty-time").innerText = tyLeft + "s";
if (tyLeft <= 0) {
clearInterval(tyTimer);
document.getElementById("ty-input").disabled = true;
}
}, 1000);
}
var ok = 0;
for (var i = 0; i < inp.length; i++) {
if (inp[i] === tgt[i]) ok++;
}
var mins = Math.max((60 - tyLeft) / 60, 1 / 60);
document.getElementById("ty-wpm").innerText = Math.round((ok / 5) / mins);
document.getElementById("ty-acc").innerText = (inp.length ? Math.round((ok / inp.length) * 100) : 100) + "%";
}

function resetTypingTest() {
clearInterval(tyTimer);
tyLeft = 60;
tyRunning = false;
var el = document.getElementById("ty-input");
if (el) {
el.disabled = false;
el.value = "";
}
document.getElementById("ty-time").innerText = "60s";
document.getElementById("ty-wpm").innerText = "0";
document.getElementById("ty-acc").innerText = "100%";
}

